          { partName: "Glow Plugs", category: "Ignition", oem: { brand: "BMW Genuine", code: "12237786869", approxPrice: "30 EUR" }, crossRef: { brand: "Bosch", code: "0250402002", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=12237786869", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=12237786869" }, note: "Requires 6 units. Enables DPF regen." },
          { partName: "ZF 6HP Transmission Pan/Filter", category: "Transmission", oem: { brand: "BMW Genuine", code: "24152333903", approxPrice: "220 EUR" }, crossRef: { brand: "ZF", code: "0501.216.243", approxPrice: "90 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=24152333903", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=24152333903" }, note: "CRITICAL: Fluid and filter service." }
