          ignitionAndEngine: [ 
            { interval: "Immediately", timeLimit: "Unlimited", task: "Vacuum Hose Overhaul", details: "CRITICAL: Replace all under-hood rubber vacuum lines with silicone to cure complex tri-turbo spool issues, lag, and limp mode. Without this, you will chase boost leaks forever.", parts: ["Silicone Hoses", "Pierburg Converters"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Replacement", details: "CRITICAL: The single-row rear timing chain stretches and snaps under the M50d torque. Requires dropping the transmission or pulling the engine to replace all chains and guides.", parts: ["IWIS Chain Kit"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1,500 - 2,500 EUR" },
            { interval: "Immediately", timeLimit: "Unlimited", task: "EGR Cooler Recall Check", details: "CRITICAL: Verify that the revised EGR cooler is installed to prevent catastrophic engine bay fires.", parts: ["BorgWarner Cooler"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "0 EUR (Recall)" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifold and blast the thick carbon sludge from the intake ports caused by aggressive Euro 5 EGR operation.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "400 EUR" },
            { interval: "120,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "Proactively replace the massive main crankshaft pulley before the rubber core shears and destroys the serpentine belt under the immense torque.", parts: ["Corteco Damper", "Stretch Bolts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay Replacement", details: "Replace all 6 glow plugs and the vulnerable control module. Essential for triggering DPF regens.", parts: ["6x Plugs", "Relay Module"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }
          ],
