            { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifold and blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "350 EUR" },
            { interval: "50,000 km", timeLimit: "5 years", task: "Spark Plug Replacement", details: "Direct injected turbo engines eat spark plugs rapidly. Replace to prevent severe misfires under heavy boost.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["6x Eldor/Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "240 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Valvetronic Eccentric Shaft & Motor", details: "If the engine throws persistent Valvetronic codes and goes into limp mode, the expensive eccentric shaft teeth and servomotors must be replaced.", parts: ["Shaft", "Motor", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "1,500 - 2,500 EUR" }
