          fluidsAndDrivetrain: [ 
            { interval: "60,000 km", timeLimit: "5 years", task: "Two-Mode Transmission Fluid", details: "CRITICAL: Drain and refill the highly specialized hybrid transmission fluid. Do NOT use standard ATF. This transmission is unrepairable if it fails.", parts: ["BMW Hybrid Fluid"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "600 EUR" }, 
            { interval: "60,000 km", timeLimit: "5 years", task: "Transfer Case Fluid", details: "Drain and refill transfer case fluid and RESET adaptations via software to prevent AWD binding.", parts: ["0.9L DTF-1"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Front & Rear Differential Oil", details: "Extract and carefully refill both differentials.", parts: ["2.0L 75W-90 Synthetic"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "140 EUR" },
            { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush and bleed the DOT 4 LV fluid thoroughly.", parts: ["1.0L DOT 4 LV"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" },
            { interval: "60,000 km", timeLimit: "4 years", task: "Engine Coolant Flush", details: "Drain and refill the main engine circuit, charge-air cooler circuit, and the dedicated High-Voltage Battery cooling circuit with BMW HT-12 coolant.", parts: ["21.5L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" }
          ],
          oilAndFilters: [ 
            { interval: "8,000 km", timeLimit: "1 year", task: "Engine Oil & Filter Change", details: "CRITICAL: The N63 'Hot-V' obliterates engine oil. Changing oil every 8,000 km is the ONLY way to protect the weak timing chains and massive turbos. NEVER follow factory intervals.", parts: ["8.5L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "130 EUR" }, 
            { interval: "30,000 km", timeLimit: "3 years", task: "Engine Air Filters (x2)", details: "Replace the dual panel filters.", parts: ["2x Air Filters"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "40 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Fuel Filter", details: "Integrated into the low-pressure fuel pump assembly inside the tank.", parts: ["In-Tank Assembly"], importance: "Low", laborDifficulty: "Advanced", estimatedCost: "200 EUR" },
            { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "35 EUR" }
          ],
          ignitionAndEngine: [ 
            { interval: "Immediately", timeLimit: "Unlimited", task: "Index 11/12 Injector Upgrade", details: "CRITICAL: If the engine has early Piezo injectors, they WILL leak fuel and cause catastrophic engine hydrolock. Upgrade all 8 immediately.", parts: ["8x Index 12 Injectors"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "2,000 - 3,000 EUR" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Hot-V Coolant Line Overhaul", details: "CRITICAL: Replace the plastic/rubber coolant 'T-fittings' and turbo lines before they crack and cause an engine fire. Upgrade to billet aluminum fittings if possible.", parts: ["Coolant Line Kit", "Billet Tees"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" },
            { interval: "120,000 km", timeLimit: "Unlimited", task: "Valve Stem Seal Replacement", details: "CRITICAL: When the engine starts smoking blue out the exhaust after idling, you MUST replace the valve stem seals using the AGA tool method.", parts: ["Elring Seal Kit", "AGA Tool Rental"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "2,000 - 3,000 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain Replacement", details: "CRITICAL: The original timing chains stretch under the V8 torque. Proactive replacement is highly recommended to prevent piston-to-valve contact.", parts: ["IWIS Chain Kit"], importance: "High", laborDifficulty: "Expert", estimatedCost: "2,500 - 3,500 EUR" },
            { interval: "80,000 km", timeLimit: "6 years", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber profile gasket. If oil drips onto the serpentine belt, the engine will ingest it and die.", parts: ["Genuine BMW Gasket"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "30 EUR (Part) / 300 EUR (Labor)" },
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifolds and blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "500 EUR" },
            { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plug Replacement", details: "Twin-turbo V8s eat spark plugs rapidly. Replace to prevent severe misfires under heavy boost.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["8x Eldor/Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "250 EUR" }
          ],
