            { interval: "30,000 km", timeLimit: "3 years", task: "Engine Air Filters (x2)", details: "Replace the dual panel filters.", parts: ["2x Air Filters"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "50 EUR" },
            { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "45 EUR" }
