          ignitionAndEngine: [ 
            { interval: "80,000 km", timeLimit: "Unlimited", task: "Hot-V Coolant Line Overhaul", details: "CRITICAL: Replace the plastic/rubber coolant 'T-fittings' and turbo lines before they crack and cause an engine fire. Upgrade to billet aluminum fittings if possible.", parts: ["Coolant Line Kit", "Billet Tees"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Valve Stem Seal Replacement", details: "When the engine starts smoking blue out the exhaust after idling, you MUST replace the valve stem seals using the AGA tool method.", parts: ["Elring Seal Kit", "AGA Tool Rental"], importance: "High", laborDifficulty: "Expert", estimatedCost: "2,000 - 3,000 EUR" },
            { interval: "80,000 km", timeLimit: "6 years", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber profile gasket. If oil drips onto the serpentine belt, the engine will ingest it and die.", parts: ["Genuine BMW Gasket"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "30 EUR (Part) / 300 EUR (Labor)" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifolds and blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "500 EUR" },
            { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plug Replacement", details: "Twin-turbo V8s eat spark plugs rapidly. Replace to prevent severe misfires under heavy boost.", parts: ["8x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["8x Eldor Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "300 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Valvetronic Eccentric Shaft & Motor", details: "If the engine throws persistent Valvetronic codes and goes into limp mode, the expensive eccentric shaft teeth and servomotors must be replaced.", parts: ["Shaft", "Motor", "Massive Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "2,000 - 3,000 EUR" }
          ],
