          { partName: "Glow Plugs", category: "Ignition", oem: { brand: "BMW Genuine", code: "12237786869", approxPrice: "30 EUR" }, crossRef: { brand: "Bosch", code: "0250402002", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=12237786869", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=12237786869" }, note: "Requires 6 units. Enables DPF regen." },
          { partName: "Serpentine Belt", category: "Engine", oem: { brand: "BMW Genuine", code: "11288596205", approxPrice: "60 EUR" }, crossRef: { brand: "Continental", code: "6PK1003", approxPrice: "20 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=11288596205", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=11288596205" }, note: "Replace with tensioner." },
          { partName: "Water Pump", category: "Cooling", oem: { brand: "BMW Genuine", code: "11518632585", approxPrice: "280 EUR" }, crossRef: { brand: "Pierburg", code: "7.07856.08.0", approxPrice: "160 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=11518632585", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=11518632585" }, note: "Mechanical pump, highly reliable." }
