            { interval: "As Needed", timeLimit: "Unlimited", task: "PCV Diaphragm Replacement", details: "If the engine develops a loud whistle or rough idle, replace the torn rubber PCV diaphragm immediately.", parts: ["Vaico Repair Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifold (which houses the intercooler) and blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "450 EUR" },
            { interval: "60,000 km", timeLimit: "6 years", task: "Spark Plug Replacement", details: "Direct injected turbo engines eat spark plugs rapidly. Replace to prevent severe misfires under heavy boost.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "130 EUR" },
            { interval: "120,000 km", timeLimit: "8 years", task: "Heat Management Module & Water Pump", details: "If mysterious coolant loss occurs, the complex thermostat module and mechanical water pump must be replaced.", parts: ["INA Module", "Pierburg Pump"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "650 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["6x Eldor Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "250 EUR" }
