            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belts & Tensioners", details: "Replace the main drive belt and tensioner.", parts: ["Continental Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "130 EUR" }
