          { partName: "Spark Plugs", category: "Ignition", oem: { brand: "BMW Genuine", code: "12120040551", approxPrice: "30 EUR" }, crossRef: { brand: "NGK", code: "SILZKGR8B8S", approxPrice: "18 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=12120040551", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=12120040551" }, note: "Requires 6 units. Specific to B58." },
          { partName: "Ignition Coil", category: "Ignition", oem: { brand: "BMW Genuine", code: "12138643360", approxPrice: "65 EUR" }, crossRef: { brand: "Eldor", code: "R3516S00100", approxPrice: "40 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=12138643360", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=12138643360" }, note: "Requires 6 units." },
          { partName: "Serpentine Belt", category: "Engine", oem: { brand: "BMW Genuine", code: "11288596205", approxPrice: "60 EUR" }, crossRef: { brand: "Continental", code: "6PK1003", approxPrice: "20 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=11288596205", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=11288596205" }, note: "Replace with tensioner." },
          { partName: "ZF 8HP Transmission Pan/Filter", category: "Transmission", oem: { brand: "BMW Genuine", code: "24118612901", approxPrice: "250 EUR" }, crossRef: { brand: "ZF", code: "1087.298.364", approxPrice: "120 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=24118612901", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=24118612901" }, note: "CRITICAL: Fluid and filter service." },
          { partName: "Front Thrust Arms (Control Arms)", category: "Suspension", oem: { brand: "BMW Genuine", code: "31126864821", approxPrice: "280 EUR" }, crossRef: { brand: "Lemförder", code: "39401 01", approxPrice: "150 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=31126864821", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=31126864821" }, note: "Fixes severe G07 braking shimmy." },
          { partName: "Engine Air Filter", category: "Filters", oem: { brand: "BMW Genuine", code: "13718692202", approxPrice: "45 EUR" }, crossRef: { brand: "Mann Filter", code: "C 28 038", approxPrice: "25 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=13718692202", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=13718692202" }, note: "Standard replacement interval." }
