          { partName: "Air Suspension Spring (Front)", category: "Suspension", oem: { brand: "BMW Genuine", code: "37106885366", approxPrice: "1200 EUR" }, crossRef: { brand: "Arnott", code: "AS-3382", approxPrice: "600 EUR", source: "Premium Upgrade", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=37106885366", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=37106885366" }, note: "Replace if sagging occurs." }
